def comps(g):
 h,w=len(g),len(g[0]); seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=4 or (r,c) in seen:continue
   st=[(r,c)];seen.add((r,c));co=[]
   while st:
    a,b=st.pop();co.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+da,b+db
     if 0<=x<h and 0<=y<w and g[x][y]==4 and (x,y) not in seen:seen.add((x,y));st.append((x,y))
   cs.append(co)
 return sorted(cs,key=len,reverse=True)
